export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a new job with the given job_id. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' }
        },
        required: ['job_id']
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job by job_id. Rejects missing jobs or already-cancelled jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Identifier of the job to cancel.' }
        },
        required: ['job_id']
      }
    }
  ];
}

