  if (!isText(job_id)) {
    throw error(-32602, 'job_id is required and must be a non-empty string');
  }
  const job = jobs.get(job_id);
  if (!job) {
    throw error(-32602, `job '${job_id}' not found`);
  }
  if (job.status === 'cancelled') {
    throw error(-32602, `job '${job_id}' is already cancelled`);
  }
  job.status = 'cancelled';
  return {
    content: [{ type: 'text', text: `job '${job_id}' cancelled` }]
  };
}
