import { callTool, listTools } from './server.mjs';
import assert from 'node:assert/strict';

// listTools
const tools = await listTools();
assert.equal(tools.length, 2);
assert.equal(tools[0].name, 'start_job');
assert.equal(tools[1].name, 'cancel_job');
assert.ok(tools[0].inputSchema.required.includes('job_id'));
assert.ok(tools[1].inputSchema.required.includes('job_id'));

// start returns running
const r = await callTool('start_job', { job_id: 'a' });
assert.match(r.content[0].text, /running/);

// duplicate active job rejected
await assert.rejects(() => callTool('start_job', { job_id: 'a' }), /already running/);

// cancel missing rejected
await assert.rejects(() => callTool('cancel_job', { job_id: 'nope' }), /not found/);

// repeated cancellation rejected
await callTool('cancel_job', { job_id: 'a' });
await assert.rejects(() => callTool('cancel_job', { job_id: 'a' }), /already cancelled/);

// validation: missing job_id
await assert.rejects(() => callTool('start_job', {}), /job_id/);
await assert.rejects(() => callTool('cancel_job', {}), /job_id/);

// unknown tool
await assert.rejects(() => callTool('bogus', {}), /Method not found/);

console.log('all edge cases OK');
""}

